O<-"/path/to/storage/kleiber_birds_gemcat/results/growth_regulators_2026-10-21_v1";out<-list();for(panel in c("ma2016","bird_F12","bird_E_label")){d<-read.delim(file.path(O,"audit",paste0("verify_",panel,".tsv")));C<-as.matrix(read.delim(file.path(O,"audit",paste0("verify_",panel,"_C.tsv")),header=FALSE));L<-t(chol(C));y<-solve(L,d$y);X<-solve(L,cbind(1,d$x));s<-summary(lm(y~X-1));out[[panel]]<-data.frame(panel=panel,beta=coef(s)[2,1],p=coef(s)[2,4])};write.table(do.call(rbind,out),file.path(O,"audit/GLS_baseR.tsv"),row.names=FALSE,sep="\t",quote=FALSE)